<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($store['name']) ?> · Installation report</title><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script></head><body class="report-page"><div class="report-toolbar"><a class="button" href="<?= e(url('store',['id'=>$store['id']])) ?>">Back to store</a><button class="button primary print-report">Print / Save as PDF</button></div><main class="report-document"><header class="report-header"><span class="eyebrow">JJ PROJECT MANAGEMENT · INSTALLATION REPORT</span><h1><?= e($store['name']) ?></h1><p><?= e($store['code']) ?> · <?= e($store['city']) ?> · Installation: <?= e($store['target_date']?:'Not scheduled') ?></p><p>Address: <?= e(trim(($store['address']??'').' · '.($store['post_code']??'').' '.$store['city'],' ·')) ?></p><p>Store owner: <?= e($store['owner_name']?:'Not set') ?> · <?= e($store['owner_email']?:'') ?></p><small>Generated <?= e(gmdate('Y-m-d H:i')) ?> UTC · <?= count(array_filter($steps,fn($s)=>(bool)$s['signed_at'])) ?> / <?= count($steps) ?> steps signed off</small></header>
<?php foreach($steps as $index=>$step): ?><section class="report-step"><div class="report-step-heading"><span><?= $index+1 ?></span><div><small><?= e(ProjectRepository::CATEGORIES[$step['category']]) ?></small><h2><?= e($step['title']) ?></h2></div><strong><?= $step['signed_at']?'Signed off':($step['complete']?'Awaiting sign-off':'Incomplete') ?></strong></div><p><?= nl2br(e($step['instructions'])) ?></p><div class="report-note"><strong>Contractor notes</strong><p><?= nl2br(e($step['note']?:'No notes recorded.')) ?></p></div><div class="report-photos"><?php foreach($subtasks->photos($step['id']) as $photo): ?><figure><img src="<?= e(url('photo',['id'=>$photo['id']])) ?>" alt="<?= e($photo['original_name']) ?>"><figcaption><?= e($photo['original_name']) ?></figcaption></figure><?php endforeach; ?></div><p class="report-signature">Completed by <?= e($step['completed_name']?:'—') ?> · <?= e($step['completed_at']?:'—') ?><br>PM sign-off: <?= e($step['signed_name']?:'Pending') ?> · <?= e($step['signed_at']?:'—') ?></p></section><?php endforeach; ?><?php if($pmNotes): ?><section class="report-pm-notes"><h2>Project Manager notes</h2>
<?php foreach($pmNotes as $pmNote): ?><article class="report-note"><p><strong><?= e($pmNote['author_name']) ?></strong> · <?= e((new DateTimeImmutable($pmNote['created_at']))->setTimezone(new DateTimeZone('Europe/Copenhagen'))->format('Y-m-d H:i:s T')) ?></p><p><?= nl2br(e($pmNote['note'])) ?></p></article><?php endforeach; ?>
</section><?php endif; ?></main></body></html>
